# Held-out agentic bench: 40 tasks the SFT set never saw.
#
# The four built-in tasks are the ones the harness was designed against, and
# conclusions drawn from them are anecdotes. This bench is generated by the
# same synth.py but with another seed: other ports, endpoint and parameter
# names, shell commands, path-join styles, eval scopes and blacklists. A task is
# kept only after a payload actually solved it on a fresh stand, so no task has
# an impossible goal.
#
# Usage:
#   powershell -ExecutionPolicy Bypass -File scripts\21_agentic_bench.ps1
#   powershell -ExecutionPolicy Bypass -File scripts\21_agentic_bench.ps1 -Build
#   powershell -ExecutionPolicy Bypass -File scripts\21_agentic_bench.ps1 -Samples 1 -Passes 2

param(
    [string]$Model = "izumxai:9b-v6",
    [string]$Baseline = "izumxai:9b-v4",
    [int]$Tasks = 40,
    [int]$Samples = 1,
    [int]$Passes = 1,
    [int]$MaxSteps = 6,
    [switch]$Build
)

$ErrorActionPreference = "Stop"
$root = Split-Path -Parent $PSScriptRoot
Set-Location $root
$py = ".\.venv\Scripts\python.exe"
$env:PYTHONPATH = $root
$env:OLLAMA_MODELS = "D:\ollama\models"
$env:PYTHONUTF8 = "1"
$bench = "runs\agentic_bench\tasks"

if ($Build -or -not (Test-Path $bench)) {
    Write-Host "`n[1/2] Building $Tasks held-out tasks" -ForegroundColor Cyan
    & $py -u -m izumxai.agentic.synth --bench-out runs\agentic_bench --bench-n $Tasks
    if ($LASTEXITCODE -ne 0) { throw "bench build failed with $LASTEXITCODE" }
}

Write-Host "`n[2/2] $Model vs $Baseline, pure model, no escalation" -ForegroundColor Cyan
& $py -u -m izumxai.agentic.harness `
    --model $Baseline --model $Model `
    --tasks-dir $bench `
    --escalate-after 0 --samples $Samples --max-steps $MaxSteps --repeat $Passes
# Exit code 1 means "not everything solved": a measurement, not a failure.
if ($LASTEXITCODE -gt 1) { throw "harness crashed with $LASTEXITCODE" }

& $py -u -m izumxai.agentic.report
if ($LASTEXITCODE -ne 0) { throw "report failed with $LASTEXITCODE" }

Write-Host "`nDone." -ForegroundColor Green
